package com.example.crowdtransportfeedback.ui.screens
import androidx.compose.foundation.clickable; import androidx.compose.foundation.layout.*; import androidx.compose.foundation.lazy.*; import androidx.compose.material3.*; import androidx.compose.runtime.*; import androidx.compose.ui.Modifier; import androidx.compose.ui.unit.dp; import com.example.crowdtransportfeedback.profile.*; import kotlinx.coroutines.launch
@Composable fun MyProfileScreen(api:ProfileApi,onAchievements:()->Unit,onLeaderboard:()->Unit){var p by remember{mutableStateOf<ProfileDto?>(null)};var error by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();fun load(){scope.launch{runCatching{api.me()}.onSuccess{p=it}.onFailure{error="Profile unavailable offline"}}};LaunchedEffect(Unit){load()};Column(Modifier.padding(16.dp).fillMaxSize()){Text("My Profile",style=MaterialTheme.typography.headlineMedium);error?.let{Text(it)};p?.let{v->Text("${avatarSymbol(v.avatarKey)}  @${v.username}",style=MaterialTheme.typography.titleLarge);Text("Level ${v.level.level} · ${v.level.title}");Text("${v.totalXp} XP"+(if(v.level.maxLevel) " · MAX LEVEL" else " · ${v.level.currentLevelXp}/${v.level.nextLevelXp}"));Text("${v.contributionCount} contributions · ${v.differentLineCount} lines · ${v.transportTypeCount} types");Text("${v.unlockedAchievementCount}/${v.achievementTotal} achievements · Rank #${v.allTimeXpRank ?: "—"}");Text("Pinned: "+v.pinnedAchievements.joinToString{it.title});Text("Choose avatar");Row{listOf("COMMUTER","NAVIGATOR","EXPLORER").forEach{key->TextButton(onClick={scope.launch{api.avatar(mapOf("avatarKey" to key));load()}}){Text("${avatarSymbol(key)} $key")}}};v.contributionBreakdown.forEach{(k,n)->Text("$k: $n")}};Button(onClick=onAchievements){Text("Achievements")};Button(onClick=onLeaderboard){Text("Leaderboard")}}}
@Composable fun PublicProfileScreen(api:ProfileApi,username:String){var p by remember{mutableStateOf<ProfileDto?>(null)};LaunchedEffect(username){p=runCatching{api.profile(username)}.getOrNull()};Column(Modifier.padding(16.dp)){Text("Public Profile",style=MaterialTheme.typography.headlineMedium);p?.let{Text("${avatarSymbol(it.avatarKey)} @${it.username}");Text("Level ${it.level.level} · ${it.level.title} · ${it.totalXp} XP");Text("${it.contributionCount} contributions · ${it.differentLineCount} lines · ${it.transportTypeCount} types");Text("${it.unlockedAchievementCount} achievements");it.pinnedAchievements.forEach{b->Text("🏅 ${b.title}")}}}}
@Composable fun AchievementsScreen(api:ProfileApi){var badges by remember{mutableStateOf(emptyList<BadgeDto>())};val scope=rememberCoroutineScope();LaunchedEffect(Unit){badges=api.achievements()};LazyColumn(Modifier.padding(16.dp)){item{Text("Achievements ${badges.count{it.unlocked}} / 28",style=MaterialTheme.typography.headlineMedium)};badges.groupBy{it.category}.forEach{(category,list)->item{Text(category,style=MaterialTheme.typography.titleLarge)};items(list){b->Card(Modifier.fillMaxWidth().padding(4.dp).clickable(enabled=b.unlocked){scope.launch{val pins=badges.filter{it.pinned}.map{it.code}.toMutableList();if(b.pinned)pins.remove(b.code) else if(pins.size<3)pins.add(b.code);api.pins(mapOf("achievementCodes" to pins));badges=api.achievements()}}){Column(Modifier.padding(8.dp)){Text((if(b.unlocked)"🏅 " else "🔒 ")+b.title);Text(b.description);Text("${b.currentProgress} / ${b.targetProgress}"+(if(b.pinned)" · Pinned" else ""));b.unlockedAt?.let{Text("Unlocked $it")}}}}}}}
@Composable fun LeaderboardScreen(api:ProfileApi,onUser:(String)->Unit){var metric by remember{mutableStateOf("XP")};var period by remember{mutableStateOf("ALL_TIME")};var data by remember{mutableStateOf<LeaderboardDto?>(null)};LaunchedEffect(metric,period){data=runCatching{api.leaderboard(metric,period)}.getOrNull()};Column(Modifier.padding(16.dp)){Text("Leaderboard",style=MaterialTheme.typography.headlineMedium);Row{listOf("XP","ACHIEVEMENTS","CONTRIBUTIONS").forEach{TextButton(onClick={metric=it}){Text(it)}}};Row{listOf("ALL_TIME","THIS_MONTH").forEach{TextButton(onClick={period=it}){Text(it.replace('_',' '))}}};data?.currentUser?.let{Text("YOUR RANK #${it.rank?:"—"} @${it.username} · ${it.metricValue}")};LazyColumn{items(data?.top.orEmpty()){e->Text("#${e.rank} ${avatarSymbol(e.avatarKey)} @${e.username} · ${e.metricValue}",Modifier.fillMaxWidth().clickable{onUser(e.username)}.padding(8.dp))}}}}
fun avatarSymbol(key:String)=when(key){"NAVIGATOR"->"🧭";"EXPLORER"->"🗺";else->"🚏"}
